def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v_without_metadata = v.split('+')[0]

        # Split on '-' to separate core version and pre-release
        if '-' in v_without_metadata:
            core_part, prerelease_part = v_without_metadata.split('-', 1)
        else:
            core_part = v_without_metadata
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert numeric identifiers to integers for comparison
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))  # 0 indicates numeric
                else:
                    parsed_prerelease.append((1, identifier))  # 1 indicates string
        else:
            parsed_prerelease = None

        return (major, minor, patch, parsed_prerelease)

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)

        # If no pre-release, it sorts after the same version with pre-release
        # We use a tuple where prerelease is compared: None sorts after an empty list
        if prerelease is None:
            prerelease_key = (1,)  # This will sort after (0, ...)
        else:
            prerelease_key = (0, prerelease)  # Pre-release sorts first

        return (major, minor, patch, prerelease_key)

    # Sort with stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

